361	    public async Task<string?> WriteGroupedRowsAsync(
362	        Stream input,
363	        Stream output,
364	        IReadOnlyList<string> groupByArguments)
365	    {
366	        if (!GroupByRequest.TryParse(groupByArguments, out var request, out var errorMessage))
367	        {
368	            return errorMessage;
369	        }
370	
371	        using var parser = CreateParser(input);
372	
373	        var headers = parser.ReadFields();
374	        if (headers is null)
375	        {
376	            return "CSV file is empty.";
377	        }
378	
379	        if (!TryResolveColumnIndex(headers, request.GroupColumnName, out var groupColumnIndex))
380	        {
381	            return $"Column not found: {request.GroupColumnName}";
382	        }
383	
384	        var aggregateColumnIndex = -1;
385	        if (request.AggregateKind is GroupByAggregateKind.Sum)
386	        {
387	            if (!TryResolveColumnIndex(headers, request.AggregateColumnName!, out aggregateColumnIndex))
388	            {
389	                return $"Column not found: {request.AggregateColumnName}";
390	            }
391	        }
392	
393	        var groups = new List<GroupAggregation>();
394	        var groupLookup = new Dictionary<string, GroupAggregation>(StringComparer.Ordinal);
395	
396	        while (!parser.EndOfData)
397	        {
398	            var fields = parser.ReadFields();
399	            if (fields is null)
400	            {
401	                continue;
402	            }
403	
404	            var groupValue = groupColumnIndex < fields.Length ? fields[groupColumnIndex] : string.Empty;
405	            if (!groupLookup.TryGetValue(groupValue, out var aggregation))
406	            {
407	                aggregation = new GroupAggregation(groupValue);
408	                groupLookup.Add(groupValue, aggregation);
409	                groups.Add(aggregation);
410	            }
411	
412	            aggregation.RowCount++;
413	
414	            if (request.AggregateKind is not GroupByAggregateKind.Sum)
415	            {
416	                continue;
417	            }
418	
419	            var candidateValue = aggregateColumnIndex < fields.Length ? fields[aggregateColumnIndex] : string.Empty;
420	            if (!decimal.TryParse(candidateValue, NumberStyles.Number, CultureInfo.InvariantCulture, out var numericValue))
421	            {
422	                return $"Column must contain only numeric values: {request.AggregateColumnName}";
423	            }
424	
425	            aggregation.Sum += numericValue;
426	        }
427	
428	        await using var writer = CreateWriter(output);
429	        foreach (var group in groups)
430	        {
431	            var aggregateValue = request.AggregateKind is GroupByAggregateKind.Count
432	                ? group.RowCount.ToString(CultureInfo.InvariantCulture)
433	                : FormatDecimal(group.Sum);
434	
435	            await writer.WriteLineAsync(BuildCsvRow([group.GroupValue, aggregateValue])).ConfigureAwait(false);
436	        }
437	
438	        await writer.FlushAsync().ConfigureAwait(false);
439	        await output.FlushAsync().ConfigureAwait(false);
440	        return null;
441	    }
