443	    private static string BuildCsvRow(IReadOnlyList<string> fields, IReadOnlyList<int> selectedIndexes)
444	    {
445	        var selectedFields = new string[selectedIndexes.Count];
446	        for (var i = 0; i < selectedIndexes.Count; i++)
