610	    private static string EscapeCsvField(string value)
611	    {
612	        if (value.Length == 0)
613	        {
614	            return string.Empty;
615	        }
616	
617	        var requiresQuoting = value.Contains(',') ||
618	            value.Contains('"') ||
619	            value.Contains('\r') ||
620	            value.Contains('\n');

620	            value.Contains('\n');
621	
622	        if (!requiresQuoting)
623	        {
624	            return value;
625	        }
626	
627	        var escaped = value.Replace("\"", "\"\"");
628	        return $"\"{escaped}\"";
629	    }
