647	    private sealed class StringArraySequenceComparer : IEqualityComparer<string[]>
648	    {
649	        public bool Equals(string[]? x, string[]? y)
650	        {
651	            if (ReferenceEquals(x, y))
652	            {
653	                return true;
654	            }
655	
656	            if (x is null || y is null || x.Length != y.Length)
657	            {
658	                return false;
659	            }
660	
661	            for (var i = 0; i < x.Length; i++)
662	            {
663	                if (!string.Equals(x[i], y[i], StringComparison.Ordinal))
664	                {
665	                    return false;
666	                }
667	            }
668	
669	            return true;
670	        }
671	
672	        public int GetHashCode(string[] obj)
673	        {
674	            var hashCode = new HashCode();
675	            foreach (var value in obj)
676	            {
677	                hashCode.Add(value, StringComparer.Ordinal);
678	            }
679	
680	            return hashCode.ToHashCode();
681	        }
682	    }
