696	    private sealed record GroupByRequest(string GroupColumnName, GroupByAggregateKind AggregateKind, string? AggregateColumnName)
697	    {
698	        public static bool TryParse(
699	            IReadOnlyList<string> arguments,
700	            out GroupByRequest request,
701	            out string errorMessage)
702	        {
703	            if (arguments.Count is not 2 and not 3)
704	            {
705	                request = default!;
706	                errorMessage = "Invalid groupby arguments.";
707	                return false;
708	            }
709	
710	            var groupColumnName = arguments[0];
711	            var aggregateName = arguments[1];
712	
713	            if (string.Equals(aggregateName, "count", StringComparison.OrdinalIgnoreCase))
714	            {
715	                if (arguments.Count != 2)
716	                {
717	                    request = default!;
718	                    errorMessage = "Invalid groupby arguments.";
719	                    return false;
720	                }
721	
722	                request = new GroupByRequest(groupColumnName, GroupByAggregateKind.Count, null);
723	                errorMessage = string.Empty;
724	                return true;
725	            }
726	
727	            if (string.Equals(aggregateName, "sum", StringComparison.OrdinalIgnoreCase))
728	            {
729	                if (arguments.Count != 3)
730	                {
731	                    request = default!;
732	                    errorMessage = "Invalid groupby arguments.";
733	                    return false;
734	                }
735	
736	                request = new GroupByRequest(groupColumnName, GroupByAggregateKind.Sum, arguments[2]);
737	                errorMessage = string.Empty;
738	                return true;
739	            }
740	
741	            request = default!;
742	            errorMessage = $"Invalid groupby aggregate: {aggregateName}";
